window.addEventListener('DOMContentLoaded',event=>{const sidebarWrapper=document.getElementById('sidebar-wrapper');let scrollToTopVisible=!1;const menuToggle=document.body.querySelector('.menu-toggle');menuToggle.addEventListener('click',event=>{event.preventDefault();sidebarWrapper.classList.toggle('active');_toggleMenuIcon();menuToggle.classList.toggle('active')})
var scrollTriggerList=[].slice.call(document.querySelectorAll('#sidebar-wrapper .js-scroll-trigger'));scrollTriggerList.map(scrollTrigger=>{scrollTrigger.addEventListener('click',()=>{sidebarWrapper.classList.remove('active');menuToggle.classList.remove('active');_toggleMenuIcon()})});function _toggleMenuIcon(){const menuToggleBars=document.body.querySelector('.menu-toggle > .bi-list');const menuToggleTimes=document.body.querySelector('.menu-toggle > .bi-x');if(menuToggleBars){menuToggleBars.classList.remove('bi-list');menuToggleBars.classList.add('bi-x')}
if(menuToggleTimes){menuToggleTimes.classList.remove('bi-x');menuToggleTimes.classList.add('bi-list')}}
document.addEventListener('scroll',()=>{const scrollToTop=document.body.querySelector('.scroll-to-top');if(document.documentElement.scrollTop>100){if(!scrollToTopVisible){fadeIn(scrollToTop);scrollToTopVisible=!0}}else{if(scrollToTopVisible){fadeOut(scrollToTop);scrollToTopVisible=!1}}})})
function fadeOut(el){el.style.opacity=1;(function fade(){if((el.style.opacity-=.1)<0){el.style.display="none"}else{requestAnimationFrame(fade)}})()};function fadeIn(el,display){el.style.opacity=0;el.style.display=display||"block";(function fade(){var val=parseFloat(el.style.opacity);if(!((val+=.1)>1)){el.style.opacity=val;requestAnimationFrame(fade)}})()}
